using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator = new();

    // --- CalculateTotal: DataRow-driven tests ---

    [TestMethod]
    [DataRow(10.00, 2, 0.10, 22.00, DisplayName = "2 items at $10 with 10% tax")]
    [DataRow(0.00, 5, 0.20, 0.00, DisplayName = "Zero unit price yields zero total")]
    [DataRow(25.50, 0, 0.15, 0.00, DisplayName = "Zero quantity yields zero total")]
    [DataRow(100.00, 1, 0.00, 100.00, DisplayName = "No tax applied")]
    [DataRow(49.99, 3, 1.00, 299.94, DisplayName = "100% tax doubles subtotal")]
    [DataRow(0.01, 1, 0.07, 0.0107, DisplayName = "Minimum price with typical tax")]
    public void CalculateTotal_ValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, DisplayName = "Negative unit price throws")]
    [DataRow(10.00, -1, 0.10, DisplayName = "Negative quantity throws")]
    [DataRow(10.00, 1, -0.01, DisplayName = "Negative tax rate throws")]
    [DataRow(10.00, 1, 1.01, DisplayName = "Tax rate above 1 throws")]
    public void CalculateTotal_InvalidInputs_ThrowsArgumentOutOfRangeException(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    // --- ApplyDiscount: DynamicData-driven tests ---

    public static IEnumerable<object[]> DiscountTestData =>
    [
        [100m, 0m, 100m, "No discount leaves price unchanged"],
        [100m, 10m, 90m, "10% off $100"],
        [200m, 25m, 150m, "25% off $200"],
        [50m, 50m, 25m, "50% off $50"],
        [80m, 100m, 0m, "100% discount yields zero"],
        [0m, 50m, 0m, "Zero price with any discount stays zero"],
        [199.99m, 15m, 169.9915m, "Fractional price with 15% discount"],
    ];

    [TestMethod]
    [DynamicData(nameof(DiscountTestData), DynamicDataDisplayName = nameof(GetDiscountDisplayName))]
    public void ApplyDiscount_ValidInputs_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected, string scenario)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result, $"Failed for scenario: {scenario}");
    }

    public static string GetDiscountDisplayName(MethodInfo methodInfo, object[] data)
        => (string)data[3];

    [TestMethod]
    [DataRow(-0.01, DisplayName = "Discount below 0% throws")]
    [DataRow(100.01, DisplayName = "Discount above 100% throws")]
    public void ApplyDiscount_InvalidPercent_ThrowsArgumentOutOfRangeException(double discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, (decimal)discountPercent));
    }
}

